package paymentmethod

// Instructions is what the buyer sees in the checkout response.
// The `Reference` field is generated by the checkout service from the
// order ID so the merchant can reconcile bank transfers.
type Instructions struct {
	Method    string         `json:"method"`
	Label     string         `json:"label"`
	Config    map[string]any `json:"config"`
	Reference string         `json:"reference"`
}

func BuildInstructions(m *PaymentMethod, reference string) Instructions {
	return Instructions{
		Method:    string(m.Method),
		Label:     MethodLabel(m.Method),
		Config:    m.PublicView(),
		Reference: reference,
	}
}

func MethodLabel(m Method) string {
	switch m {
	case MethodPagoMovil:
		return "Pago Móvil"
	case MethodZelle:
		return "Zelle"
	case MethodUSDT:
		return "USDT (Cripto)"
	case MethodTransfer:
		return "Transferencia bancaria"
	case MethodCash:
		return "Efectivo"
	}
	return string(m)
}